import sys, os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from deck_lib import *

S = []
S.append(cover('cover', 'Process safety training', 'HAZOP<br>made practical', 'How a team finds what can go wrong before the batch does',
 'Welcome. A HAZOP is the one meeting where we are allowed to ask, again and again, what if this goes wrong. Today I want you to leave knowing how a good one runs and how to write a row that someone can act on a year from now. Everyone here has a part: operators know how the plant really behaves, engineers know the design, supervisors know the shortcuts. Let me ask first: who has sat through a HAZOP that felt like a box-ticking exercise? Keep that in mind. We will fix that today.'))
S.append(stats('what', 'What a HAZOP really is', [('1', 'node at a time'), ('7', 'guidewords to prompt ideas'), ('5', 'parameters to start with')], 'A structured way to ask: what if the process does something other than intended?',
 'A HAZOP takes the design one section at a time and asks, with a short list of guidewords, how it could deviate from what we want. (Click.) One node at a time, so we do not skip the boring pipe that causes the leak. (Click.) Seven guidewords to prompt ideas. (Click.) And five parameters to start with: flow, pressure, temperature, level and composition. (Click.) The point is structure. Ask the room: how many of you have seen a safety discussion drift into one person favourite story? Structure stops that.', 'light'))
S.append(compare('isnot', 'HAZOP is a team study, not a form to fill', ('What it is not', ['A paper exercise to get a signature', 'One engineer in an office with a template', 'A way to redesign the whole process', 'A replacement for operating procedures']), ('What it is', ['A team meeting that questions the design', 'Operators, maintenance and process in one room', 'A record of causes, consequences and safeguards', 'A list of actions with an owner and a date']),
 'First the wrong ideas. (Click.) A HAZOP is not a form to get signed, and it is not one engineer filling a template alone. It does not redesign the process; the team finds problems and records them. (Click.) What it is: different people, one room, questioning the design. The record should let someone who was not there understand the risk. Question for the room: if the plant head asked you tomorrow what the HAZOP actually changed at our plant, could you answer in one sentence? That is the test.', 'dark'))
S.append(cards('team', 'Who sits in the room', [('Leader', 'Knows the method and keeps the team on one node. Does not decide the technical answers.'), ('Scribe', 'Records causes, consequences, safeguards and actions as the team says them. Reads each row back.'), ('Operations and maintenance', 'Know how it is really run, bypassed and repaired. Without them the study is guesswork.'), ('Process and instrumentation', 'Explain the design intent, the set points, the trips and the control loops.')],
 'Roles first. (Click.) The leader runs the method, not the opinions. (Click.) The scribe writes what the team agrees, and reads it back before moving on. (Click.) Operations and maintenance: ask them what the P&ID does not show, such as the bypass hose that is always kept near the pump. (Click.) Process and instrumentation explain intent and trips. Ask the room: who should NOT lead the HAZOP on their own design? The designer, because it is hard to question your own work.'))
S.append(bullets('node', 'Start with the node and its design intent', ['A node is a section of the process with one clear purpose', 'Write the design intent in one sentence: what should happen, at what rate, between which equipment', 'List the parameters: flow, pressure, temperature, level, composition', 'Mark the node on the P&ID so everyone discusses the same pipe'],
 'Before any guideword, we agree the node. (Click.) A node is a part of the plant with one purpose, for example the solvent line from the day tank to the reactor. (Click.) Write the intent in one sentence. Without intent you cannot define a deviation. (Click.) Then pick the parameters that matter here. (Click.) And mark the node on the P&ID. Ask the room: if I said the reactor system as one node, what would we miss? Usually the small connections, vents and drains where the trouble hides.', 'dark', callout=('Intent', 'Deviation means departure from intent. No intent, no deviation.')))
S.append(table('words', 'Guidewords prompt the deviations', ['Guideword', 'Meaning', 'Example in a solvent line'], [['No / none', 'The intended thing does not happen', 'No flow'], ['Less', 'Quantity lower than intended', 'Less flow, less pressure'], ['More', 'Quantity higher than intended', 'More temperature, more level'], ['Reverse', 'Opposite direction', 'Reactor contents flow back'], ['As well as', 'Something extra is present', 'Water in the solvent'], ['Part of', 'Only part of the intent happens', 'One blend component missing'], ['Other than', 'Something different happens', 'Wrong solvent charged']],
 'Seven words, each a prompt. (Click through the rows.) No, less and more cover quantity. Reverse is direction. As well as means something extra is there. Part of means only part of the intent happens. Other than means something different happens, the wrong material for instance. Do not argue about the exact word. If the team has the idea, the word has done its job. Question: which of these do we most often forget when we discuss a transfer line? In my experience it is reverse flow.', 'light'))
S.append(table('params', 'Guideword plus parameter gives a deviation', ['Parameter', 'Deviations to ask about', 'What to think about'], [['Flow', 'No, less, more, reverse', 'Valves, pumps, strainers, non-return valves'], ['Pressure', 'Less (vacuum), more', 'Blocked outlets, vents, relief devices'], ['Temperature', 'Less, more', 'Cooling, heating, ambient, reaction heat'], ['Level', 'Less, more, no', 'Overfill, empty vessel, instrument failure'], ['Composition', 'As well as, part of, other than', 'Water, wrong material, wrong ratio']],
 'Now combine. A guideword on a parameter gives a deviation, such as more temperature or no flow. (Click through.) Not every combination makes sense, and that is fine. Say why it does not, and move on, so the record shows it was considered. Ask the room: for a reactor feed line, what would reverse pressure even mean? Usually nothing. We write not applicable and the reason. That sentence protects us later when someone asks whether we thought about it.', 'dark'))
S.append(cards('chain', 'Every row follows the same chain', [('Deviation', 'More temperature in the reactor'), ('Cause', 'Cooling water valve fails closed'), ('Consequence', 'Temperature passes the solvent boiling point and vapour is released'), ('Safeguards and action', 'High-temperature trip and alarm. Action: prove the trip works, owner and date.')],
 'This is the chain every row must follow. (Click.) Deviation first: what goes wrong. (Click.) Then cause: why it could happen. One deviation may have several causes, and each gets its own line if the consequences differ. (Click.) Then consequence: not temperature rises, but what that does to people, plant and environment. (Click.) Finally safeguards that exist today, and an action if the risk is still not acceptable. Ask the room: can a safeguard be the cause of another deviation? Yes, and we will meet that later.'))
S.append(guess('gw', 'Which guideword fits?', 'Cooling water stops flowing to the reactor jacket during the reaction.', 'No flow', 'Parameter: flow, guideword: no, in the cooling water node. The consequence belongs in the reactor row: temperature rises, pressure builds, the batch can run away.',
 'Let us practise. Cooling water stops flowing to the jacket while the reaction is going. Give the room ten seconds to shout the guideword. (Click.) No flow, in the cooling water node. Notice that the consequence appears elsewhere, in the reactor. A good HAZOP follows the consequence across nodes. If someone said less flow, that is also fair, because partial loss also matters. Ask who in the room has seen a cooling failure and what the first thing the operator did. Their answers become the safeguards we list.', 'dark'))
S.append(table('ex1', 'Worked example: charging solvent', ['Deviation', 'Cause', 'Consequence', 'Safeguards'], [['More flow', 'Charging valve left fully open', 'Reactor overcharged, vapour pushed to vent', 'Flow totaliser with cut-off'], ['Reverse flow', 'No non-return valve, reactor at higher pressure', 'Contents back to day tank, spill', 'None found: raise action'], ['Other than', 'Similar drum labels, wrong drum', 'Unplanned reaction with the reagent', 'Label check, second person']],
 'Our first worked example is a solvent charge to a batch reactor. Read the three rows. (Click each.) More flow: the totaliser with cut-off is a real safeguard, but is it tested? Reverse flow: an honest none found, and an action to fit a non-return valve. Other than: two layers, label check and second person. Ask the room: which row would you challenge? The second, because a team that writes none found is doing the job well. It is better than a made-up safeguard.', 'light'))
S.append(table('ex2', 'Worked example: cooling water failure', ['Deviation', 'Cause', 'Consequence', 'Safeguards'], [['No cooling flow', 'Pump trips, valve closes', 'Temperature rises, vapour generation increases', 'High-temperature alarm'], ['More temperature', 'Cooling fails during an exothermic step', 'Pressure above design, relief opens', 'Independent trip stops feed, relief valve'], ['Less cooling', 'Fouled jacket, low water temperature margin', 'Slower cooling, longer cycle, accumulation risk', 'Temperature trend, hold point']],
 'Second example, the one that worries most of us. Cooling water fails during the dosing step. (Click each.) Notice that an alarm alone depends on someone reacting in time. The independent trip that stops the feed works without the operator. Ask the room: how long does the operator really have between alarm and trouble? If the honest answer is a few minutes, the alarm is not enough. Then the action is to prove that the trip works and test it regularly.', 'dark'))
S.append(table('ex3', 'Worked example: agitator failure', ['Deviation', 'Cause', 'Consequence', 'Safeguards'], [['No agitation', 'Motor trips, coupling or shaft fails', 'Reagent collects unmixed, heat and reaction build up', 'Motor-run feedback, interlock on feed'], ['Less agitation', 'Wrong speed, vortex at low level', 'Poor heat transfer, local hot spots', 'Speed indication, minimum level'], ['Restart after stop', 'Operator restarts on a loaded batch', 'Sudden reaction of accumulated reagent', 'Procedure: stop, assess, then restart']],
 'Third example, easy to forget because the agitator seems harmless. (Click each.) If it stops while a reagent is being added, the reagent can collect unmixed, and when the agitator restarts everything reacts at once. That is why the interlock on the feed matters. Ask the room: what do we tell the operator to do when the agitator trips during dosing? The answer should be in the procedure, and should be written. If it is only in someone head, it is not a safeguard.', 'light'))
S.append(compare('batch', 'Batch plants add time to the study', ('Continuous plant', ['Study by node: lines and vessels', 'Parameters change slowly or not at all', 'Same conditions most of the time']), ('Batch plant', ['Study by node and by step', 'Conditions change with each step', 'Time, sequence and quantity matter', 'Operators act at every step']),
 'Batch differs from continuous in one important way. (Click.) In a continuous plant the same node sits at the same conditions most of the time. (Click.) In a batch plant the same vessel is a heater, a reactor, a still and a storage tank in the same shift. So we study the node and then each step in the batch sheet. Ask the room: how many of our incidents happened during a changeover or a manual step? The step table makes the team look at exactly those moments.', 'dark'))
S.append(cards('time', 'Time-based deviations for batch steps', [('Too early', 'Action taken before the condition is met, such as sampling before the reaction is complete'), ('Too late', 'Action after the point where it was needed, such as quench added late'), ('Wrong order', 'Heating before agitation, or reagent before solvent'), ('Step skipped', 'A required step missed, such as the nitrogen purge')],
 'These deviations replace some guidewords in a batch. (Click each.) Too early: the action happens before its condition. Too late: after the point where it was needed. Wrong order: sequence matters, heating before agitation is a classic. Step skipped: a required step is missed. We also ask about too long and too short for hold times. Ask the room: which of these is easiest to catch with an interlock and which needs training and a sign-off? Both lists matter.'))
S.append(compare('vague', 'A vague row and a useful row', ('Vague', ['Deviation: more temperature', 'Cause: cooling problem', 'Consequence: bad', 'Safeguard: operator', 'Action: be careful']), ('Useful', ['Deviation: more temperature in reactor', 'Cause: cooling valve fails closed', 'Consequence: vapour release above boiling point', 'Safeguard: independent trip stops feed', 'Action: test the trip, owner and date']),
 'Look at the two columns. (Click.) The left one is what most of us have read in old HAZOP reports: cooling problem, bad, operator, be careful. Nobody can act on it, and nobody can test it. (Click.) The right one says what fails, what happens, what exists and what must be done by whom. Ask the room: if you joined the plant next month, which would help you? Our rule is simple. A row passes if a new engineer could understand the risk and check the safeguard.', 'dark'))
S.append(table('risk', 'Rank the risk: severity times likelihood', ['Score', 'Band', 'What the team does'], [['1 to 4', 'Low', 'Accept, keep the safeguards working'], ['5 to 9', 'Medium', 'Reduce if practical, record the reason'], ['10 to 16', 'High', 'Add safeguards, action with owner and date'], ['17 to 25', 'Very high', 'Do not run until the risk is reduced']],
 'After the safeguards are listed, we ask how bad and how likely. (Click through.) Score severity one to five and likelihood one to five, with the safeguards that exist today, and multiply. The bands here are an example, and your company matrix decides the real ones. What matters is that the same team applies the same logic to every row. Ask the room: who in the plant should help judge severity? Operators who know the people nearby and the way the area is used.', 'light', note='Example bands for teaching. Use your own company risk matrix in a real study.'))
S.append(guess('score', 'Score this one', 'Cooling failure, exothermic reaction, no independent trip. Severity 4, likelihood 3.', '12: High', 'Severity 4 times likelihood 3 is 12, in the high band. The action is to add an independent trip that stops the feed, then rescore with the trip in place.',
 'Do the sum with me. (Click.) Four times three is twelve, which falls in the high band, so we need more safeguards. A common error is to score the risk without safeguards and then list safeguards and forget to rescore. Another is to lower the likelihood just because the safeguard is a procedure that people may skip. Ask the room: if we add an independent trip, what is the new likelihood and why? Be ready to defend the number, because someone will ask later.', 'dark'))
S.append(compare('indep', 'A safeguard must be independent of the cause', ('Not independent', ['High-level alarm from the same transmitter that failed reading low', 'Operator action that depends on the same alarm', 'Procedure that nobody checks']), ('Independent', ['Separate high-level switch', 'Trip on a different sensor and different logic channel', 'Relief valve sized for the scenario']),
 'This is the point most teams miss. (Click.) A safeguard that fails together with the cause is not a safeguard. If the level transmitter fails reading low and the alarm comes from the same transmitter, we have one failure, not two protections. (Click.) Independence means a different sensor, a different channel, or something that needs no instrument, like a relief valve. Ask the room: which of the safeguards at our plant share a sensor with the control loop? A quick check, and often a surprise.', 'light'))
S.append(live('live', 'Now you call it: five live checks', [('Pick the guideword', 'for what the node does'), ('Spot the weak row', 'and the useful one'), ('Cause, consequence or safeguard?', 'sort the statements'), ('Rank the risk', 'severity times likelihood'), ('Batch step deviations', 'too early, too late, wrong order')],
 'Open the live checks page now: pharmacheme.in/training/modules/hazop-made-practical/live/ . It has these five stations in this order, and a mini worksheet for the solvent feed line where the room proposes causes and safeguards before you reveal. Tick show answers immediately if you want to skip the reveal. Pick people from different roles for each station: ask maintenance about the safeguards, operations about the causes, process about the consequences. Allow about twenty minutes. Let the room argue before you click reveal, because the argument is the learning.'))
S.append(bullets('close', 'Close the actions, or the study was for nothing', ['Every action has an owner, a date and a way to show it is done', 'Track actions in one list that the plant head sees each month', 'Any change to the process or the design goes through management of change', 'Update the P&ID, the batch sheet and the procedures, then brief the operators'],
 'The meeting is the cheap part. The value comes from closing actions. (Click.) Owner, date, evidence. (Click.) A single list that someone senior reviews each month, because otherwise it ends up in a drawer. (Click.) Changes to the process or design go through management of change, so the next HAZOP starts from the right drawings. (Click.) And operators get briefed, because they live with the change. Ask the room: how many open HAZOP actions do we have at our plant right now, and who knows? If nobody knows, that is the first action.', 'light', callout=('Closed', 'An action is closed when the evidence exists, not when someone says done.')))
S.append(cards('mistakes', 'Common mistakes and how to avoid them', [('Rushing nodes', 'Fix: book enough time and keep to one node at a time'), ('Designer leads', 'Fix: use a trained leader who did not design it'), ('Listing training as the safeguard', 'Fix: ask what happens if the person is absent or slow'), ('Never rescoring', 'Fix: score after the safeguards, then act and rescore')],
 'Four mistakes I see most. (Click.) Rushing: one long day for a whole plant gives thin rows. (Click.) The designer leads, and defends the design instead of questioning it. (Click.) Training or be careful written as the safeguard, which fails the day someone is away. (Click.) And never rescoring after an action, so nobody knows if the risk went down. Ask the room: which of these have we done in the past? Be honest. The ones we admit are the ones we fix.', 'dark'))
S.append(mythfact('myth', 'Myth or fact?', [('A HAZOP is complete once every guideword has been applied.', 'Myth', 'It is complete when actions are closed and drawings are updated.'), ('Operators add little to a HAZOP.', 'Myth', 'They know how the plant is really run, including the shortcuts.'), ('Not applicable is an acceptable entry if the reason is written.', 'Fact', 'It shows the deviation was considered and why it was set aside.')],
 'Three claims, and I want the room to vote before I click. (Click.) The first is a myth. Completion is not the meeting, it is the closed actions and the updated drawings. (Click.) The second is a myth too. Operators know the shortcuts, the bypass hose and the work-arounds that no drawing shows. (Click.) The third is a fact, as long as the reason is written. Not applicable with a reason protects the team. Ask the room for a vote each time, and ask someone who got it wrong what changed their mind.', 'light'))
S.append(rules('rules', 'Five rules to take back to the plant', ['One node at a time, with a written design intent.', 'Operators and maintenance in the room.', 'Cause, consequence, safeguard, action in every row.', 'Safeguards must be independent of the cause.', 'Close every action, then update the drawings.'],
 'Read the five rules aloud and ask the room to repeat the last one. Then take questions. If time allows, ask each table to name the one rule that is most often missed at our plant, and one action that they can take next week. Write those on the board. The best HAZOP is the one whose actions are done. Thank everyone for the time, and remind them that the live checks page stays open for anyone who wants to practise again with their own team.'))

n = build('hazop-made-practical', 'HAZOP made practical', S)
print('hazop-made-practical', n, 'slides')
